#include <algorithm>
using namespace std;

vector<long long> list, subsets;

void generateSubsets(int index, long long currentSum) {
    if (index == (int)list.size()) {
        subsets.push_back(currentSum);
        return;
    }
    generateSubsets(index + 1, currentSum + list[index]);
    generateSubsets(index + 1, currentSum);
}

bool verify(long long M, long long W, long long x) {
    if (x == M) return true;

    long long tempX = x + M;
    while (tempX > 0) {
        if (tempX % W > 1) {
            return false;
        }
        tempX /= W;
    }
    return true;
}

int main() {
    string line;
    getline(cin, line);
    istringstream iss(line);
    long long W, M;
    iss >> W >> M;

    if (W == 2) {
        cout << "YES" << endl;
        return 0;
    }

    list.clear();
    list.push_back(1LL);
    list.push_back(W);

    long long current = W;
    const long long MAX_LIMIT = (long long)1e10;

    while (true) {
        current *= W;
        if (current < 0 || current > MAX_LIMIT) break;
        list.push_back(current);
    }

    subsets.clear();
    generateSubsets(0, 0);

    bool result = false;
    for (long long x : subsets) {
        result |= verify(M, W, x);
        if (result) break;
    }

    cout << (result ? "YES" : "NO") << endl;
    return 0;
}
